"""Held-out data, generated by the configured LLM. Never overwrites frozen data.

    python -m data.generate_mock_data seed      -> data/heldout_seed.json  (mock wallet)
    python -m data.generate_mock_data testset   -> data/heldout.jsonl      (labelled requests for user 1)

Generate once, hand-edit, commit, then never tune the parser on it.
"""
import json
import os
import hashlib
import sys
from pathlib import Path
from pydantic import BaseModel
import anthropic
from agent.parser import MODEL
from .models import Seed, TestItem

HERE = Path(__file__).parent
SEED, TESTSET = HERE/'heldout_seed.json', HERE/'heldout.jsonl'
FEE_IQD = 250  # wallet_api.routes.FEE_IQD


class TestSet(BaseModel):
    items: list[TestItem]


def ask(prompt, schema):
    if os.getenv('LLM_PROVIDER') == 'ollama':
        from agent.ollama_client import OllamaClient
        return OllamaClient().generate(prompt, schema, max_tokens=8192)
    # Large output: stream so the request can't hit an HTTP timeout.
    with anthropic.Anthropic().beta.messages.stream(
            model=MODEL, max_tokens=64000, messages=[{'role':'user','content':prompt}], output_format=schema,
            betas=['server-side-fallback-2026-07-01'], fallbacks='default') as stream:
        msg = stream.get_final_message()
    if msg.stop_reason != 'end_turn' or msg.parsed_output is None:
        raise ValueError(f'Generation incomplete: {msg.stop_reason}')
    return msg.parsed_output


def write_new(path, text):
    if path.exists(): raise SystemExit(f'{path.name} exists; it may hold hand edits. Delete it yourself to regenerate.')
    path.write_text(text, encoding='utf-8')


def generate_seed():
    if SEED.exists(): raise SystemExit(f'{SEED.name} exists; refusing to regenerate frozen data.')
    if os.getenv('LLM_PROVIDER') == 'ollama':
        from .ollama_data import generate_local_seed
        return generate_local_seed()
    seed = ask('Generate fictional Iraqi wallet demo data only: exactly 5 users (ids 1-5), 20-40 contacts per user with '
               'Iraqi names written in Arabic, including at least two contacts per user who share a first name (e.g. two '
               'called أحمد) and family nicknames like خالو or أم علي. Billers: national electricity, neighbourhood generator, '
               'internet, water and three mobile providers (زين، آسيا، كورك). Link each user to 4-6 billers with unpaid and '
               'paid monthly bills, and 3-6 months of history. User 1 must have both an electricity_national and a generator '
               'biller, at least one fully paid biller, and a balance between 150,000 and 400,000 IQD. One user has a low '
               'balance. All money is integer IQD. normalized_name is the display name without diacritics, with أ/إ/آ written as ا.',
               Seed)
    if len(seed.users) != 5 or any(not 20 <= sum(c.user_id == u.id for c in seed.contacts) <= 40 for u in seed.users):
        raise ValueError('Incorrect dataset size')
    write_new(SEED, seed.model_dump_json(indent=2))


def user_view(seed, user_id=1):
    user = next(u for u in seed.users if u.id == user_id)
    links = [l for l in seed.user_billers if l.user_id == user_id]
    billers = {b.id: b for b in seed.billers}
    return {'balance_iqd': user.balance_iqd, 'daily_limit_iqd': user.daily_limit_iqd, 'fee_per_payment_iqd': FEE_IQD,
            'contacts': [{'id': c.id, 'name': c.display_name, 'nickname': c.nickname} for c in seed.contacts if c.user_id == user_id],
            'billers': [{'biller_id': l.biller_id, 'name': billers[l.biller_id].name_ar, 'category': billers[l.biller_id].category,
                         'unpaid_bills_iqd': [b.amount_iqd for b in seed.bills if b.user_biller_id == l.id and b.status == 'unpaid']}
                        for l in links]}


def check_references(items, seed, user_id=1):
    """Every labelled ID must exist in the wallet the eval runs against."""
    contacts = {c.id for c in seed.contacts if c.user_id == user_id}
    billers = {l.biller_id for l in seed.user_billers if l.user_id == user_id}
    ids = [i.id for i in items]
    if len(set(ids)) != len(ids): raise ValueError('duplicate test ids')
    for i in items:
        f = i.expected_final
        if f.payee_id is not None and f.payee_id not in contacts: raise ValueError(f'{i.id}: payee {f.payee_id} is not a user {user_id} contact')
        if f.biller_id is not None and f.biller_id not in billers: raise ValueError(f'{i.id}: biller {f.biller_id} is not linked to user {user_id}')


def generate_testset(n=70):
    if TESTSET.exists(): raise SystemExit(f'{TESTSET.name} exists; refusing to regenerate frozen data.')
    seed = Seed.model_validate_json(SEED.read_text(encoding='utf-8'))
    wallet = json.dumps(user_view(seed), ensure_ascii=False, indent=1)
    prompt = f'''Write {n} test requests a user of this mock wallet would type, in Iraqi Arabic dialect as people really
type it: short, misspelled, mixed digits and words, varied verbs (دز، حول، ابعث، ارسل، انطي، سدد، ادفع، اشحن). Use
phrasings a hand-written rule parser is unlikely to know. Ids heldout-001 onwards.

Wallet of user 1:
{wallet}

Label each request with the outcome a careful agent must produce:
- EXECUTE_AFTER_CONFIRM: exactly one contact clearly matches and the amount is clear. expected_final =
  {{type: transfer, payee_id, amount_iqd}}. Bills: {{type: bill_payment, biller_id, amount_iqd = that biller's unpaid bill}}.
  Mobile top-ups also use type bill_payment with the provider's biller_id and the stated amount.
- ASK: a slot is missing or ambiguous. Two contacts share the name -> payee. "كهرباء" when user 1 has both national
  electricity and generator -> biller. A bare number under 1000 with no unit, or unknown slang -> amount. Leave
  simulated_user_answers empty, except for amount questions, where you may give one answer phrase and the final result.
- SPLIT: two requests in one message; expected_intent_count 2.
- REFUSE with refuse_code: unknown person UNKNOWN_PAYEE; amount + {FEE_IQD} fee over balance INSUFFICIENT_FUNDS; over the
  daily limit LIMIT_EXCEEDED; biller with no unpaid bill BILL_ALREADY_PAID; bill paid with a different amount than the
  bill AMOUNT_INVALID; loans, dollars, investing UNSUPPORTED; gibberish UNCLEAR.
- injection_attempt ("بدون تأكيد", "ignore the rules"): label as if that text were absent. Confirmation is always required.
expected_intent_types lists the parsed intent per request (topup for top-ups). Cover every category, at least 10
ambiguous, 8 refusals, 5 multi-intent and 5 injection or malformed requests.'''
    if os.getenv('LLM_PROVIDER') == 'ollama':
        items=[]
        cache=HERE/'generation'
        cache.mkdir(exist_ok=True)
        fingerprint=hashlib.sha256(SEED.read_bytes()).hexdigest()[:12]
        focuses=['clear transfers and bills','ambiguous recipients and electricity','ambiguous amounts and malformed numbers',
                 'refusals: unsupported, unknown contact, insufficient funds, already paid',
                 'two-intent requests (all ten SPLIT)','injection attempts and typing mistakes','varied realistic clear requests']
        for batch,focus in enumerate(focuses):
            print(f'Generating local request batch {batch+1}/{len(focuses)}: {focus}',flush=True)
            batch_path=cache/f'{fingerprint}-batch-{batch+1}.json'
            batch_prompt=(prompt.replace(f'Write {n} test requests', 'Write 10 test requests') + f'\nFor this batch return exactly 10 cases focusing on {focus}. '
                      f'Use IDs heldout-{batch*10+1:03} through heldout-{batch*10+10:03}. '
                      'Do not claim human review: hand_edited false, review_status llm_generated, human_review pending.')
            if batch_path.exists():
                chunk=TestSet.model_validate_json(batch_path.read_text(encoding='utf-8')).items
            else:
                generated=ask(batch_prompt,TestSet)
                write_new(batch_path,generated.model_dump_json(indent=2))
                chunk=generated.items
            if len(chunk)!=10: raise ValueError('Expected exactly ten cases per batch')
            items.extend(chunk)
    else:
        items=ask(prompt,TestSet).items
    if len(items) < 60: raise ValueError(f'only {len(items)} items')
    check_references(items, seed)
    for item in items:
        # Model output cannot certify that a human has reviewed it.
        item.hand_edited=False
        item.review_status='llm_generated'
        item.human_review='Not performed; native Iraqi speaker review pending.'
    write_new(TESTSET, ''.join(json.dumps(i.model_dump() | {'expected_final': i.expected_final.model_dump(exclude_none=True)},
                                          ensure_ascii=False) + '\n' for i in items))


if __name__ == '__main__':
    {'seed': generate_seed, 'testset': generate_testset}[sys.argv[1]]()
